//! `dif connect` — point an existing workspace at dif.sh Cloud.
//!
//! Writes the publishable key into `dif/config.yaml` and forces cloud events
//! mode, preserving comments and every other setting. Meant to be copy/pasted
//! straight from the cloud onboarding screen. It does not build — the generated
//! client is regenerated by `dif build`, which the success message points at.

use super::{validate_publishable_key, CmdError};
use crate::cloud::{rejected, ApiError, Client, CloudEnv, Failure, DEFAULT_CLOUD_URL};
use clap::Args as ClapArgs;
use console::{style, Term};
use dialoguer::Select;
use dif_core::config::EventsMode;
use dif_core::config_edit::upsert_events_block;
use dif_core::paths;
use dif_core::workspace::WorkspaceError;
use dif_core::Workspace;
use serde_json::{json, Value};
use std::io::IsTerminal;
use std::path::Path;
use std::process::ExitCode;

/// `dif connect` flags.
#[derive(ClapArgs, Debug)]
pub struct Args {
    /// Publishable key (dif_pk_…) from your dif.sh Cloud project. Written to
    /// dif/config.yaml and flowed into the generated client by `dif build`.
    /// Without it, dif connect uses your `dif auth login` session.
    #[arg(long, conflicts_with_all = ["org", "project", "create", "name"])]
    pub key: Option<String>,

    /// Cloud base URL. Only needed for self-hosted deployments; defaults to
    /// https://cloud.dif.sh.
    #[arg(long)]
    pub url: Option<String>,

    /// Org to use. Optional when you belong to one org.
    #[arg(long)]
    pub org: Option<String>,

    /// Link to this existing project.
    #[arg(long)]
    pub project: Option<String>,

    /// Create a new project.
    #[arg(long)]
    pub create: bool,

    /// Name for --create. Defaults to the workspace folder name.
    #[arg(long)]
    pub name: Option<String>,
}

/// The Cloud project that a logged-in connect selected.
#[derive(Debug)]
struct Link {
    slug: String,
    org: String,
    created: bool,
    key: String,
    dashboard_url: String,
    cloud_url: String,
    repo: Value,
}

/// Entrypoint.
pub fn run(args: Args, json: bool) -> Result<ExitCode, CmdError> {
    let key = args
        .key
        .as_deref()
        .map(validate_publishable_key)
        .transpose()?;
    if key.is_none() && args.project.is_some() && args.create {
        let f = Failure::new("usage", 2, "--project and --create can't be combined");
        return Ok(f.report(json));
    }
    let cwd = std::env::current_dir()?;

    let workspace = match Workspace::load(&cwd) {
        Ok(ws) => ws,
        Err(WorkspaceError::NotFound(_)) => {
            report_no_workspace(json);
            return Ok(ExitCode::from(2));
        }
        Err(e) => return Err(e.into()),
    };

    let (key, link) = match key {
        Some(k) => (k, None),
        None => {
            let interactive = !json && Term::stderr().is_term() && std::io::stdin().is_terminal();
            let folder = workspace
                .root
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_else(|| "app".to_string());
            let env = CloudEnv::from_process();
            match link_project(&workspace.root, &args, &env, interactive, &folder) {
                Ok(l) => (l.key.clone(), Some(l)),
                Err(f) => return Ok(f.report(json)),
            }
        }
    };
    let url = events_url(
        args.url.clone(),
        link.as_ref().map(|l| l.cloud_url.as_str()),
        workspace.config.events().url.as_deref(),
    );

    let switched_from_custom = workspace.config.events().mode == EventsMode::Custom;
    let config_path = workspace.root.join(paths::CONFIG_FILE);
    let source = std::fs::read_to_string(&config_path)?;

    let updated = upsert_events_block(&source, EventsMode::Cloud, url.as_deref(), Some(&key))
        .map_err(|_| {
            CmdError::Other(
                "could not update dif/config.yaml automatically — edit the events: block by hand",
            )
        })?;
    std::fs::write(&config_path, updated)?;

    report_success(switched_from_custom, link.as_ref(), json);
    Ok(ExitCode::from(0))
}

/// The `events.url` to write, or `None` to keep the current line.
fn events_url(
    flag: Option<String>,
    session: Option<&str>,
    current: Option<&str>,
) -> Option<String> {
    // Rewrite a stale url, so events reach the session host.
    flag.or_else(|| {
        session
            .filter(|u| *u != DEFAULT_CLOUD_URL || current.is_some())
            .map(String::from)
    })
}

fn link_project(
    root: &Path,
    args: &Args,
    env: &CloudEnv,
    interactive: bool,
    folder: &str,
) -> Result<Link, Failure> {
    let session = env
        .session()
        .ok_or_else(|| Failure::new("not_logged_in", 2, "run dif auth login"))?;
    let client = Client::new(&session.cloud_url, Some(session.token.clone()));
    let fail = |e: ApiError| rejected(env, &session, e);

    let whoami = client.get("/v1/cli/whoami").map_err(fail)?;
    let orgs = whoami["orgs"].as_array().cloned().unwrap_or_default();
    let org = match &args.org {
        Some(slug) if orgs.iter().any(|o| o["slug"] == slug.as_str()) => Some(slug.clone()),
        Some(slug) => {
            return Err(Failure::new(
                "org_not_found",
                2,
                format!("no org {slug} for this login"),
            ))
        }
        None if orgs.len() == 1 => orgs[0]["slug"].as_str().map(String::from),
        None => None,
    };
    let detected = detect_github_repo(root);

    let choice = match (&args.project, args.create, &org) {
        (Some(slug), _, _) => Some(Choice::Existing(slug.clone())),
        (None, true, Some(o)) => Some(Choice::Create(o.clone())),
        (None, true, None) if interactive => prompt_org(&orgs).map(Choice::Create),
        _ if interactive => prompt(&client, &orgs, org.clone()).map_err(fail)?,
        _ => None,
    };
    let Some(choice) = choice else {
        let projects = list_projects(&client, org.as_deref()).map_err(fail)?;
        let message = if args.create {
            "choose an org: pass --org <slug> with --create"
        } else {
            "choose a project: pass --project <slug> or --create"
        };
        return Err(needs_selection(&orgs, &projects, message));
    };

    let base = client.base().to_string();
    let (slug, org, created, resp) = match choice {
        Choice::Existing(slug) => {
            let projects = list_projects(&client, org.as_deref()).map_err(fail)?;
            let not_found = || {
                Failure::new(
                    "project_not_found",
                    2,
                    format!("no project {slug} for this login"),
                )
            };
            let project = projects
                .iter()
                .find(|p| p["slug"] == slug.as_str())
                .ok_or_else(not_found)?;
            let resp = client
                .get(&format!("/v1/cli/projects/{slug}/key"))
                .map_err(|e| match e {
                    ApiError::Status { status: 404, .. } => not_found(),
                    e => fail(e),
                })?;
            let org = project["org"].as_str().unwrap_or_default().to_string();
            (slug, org, false, resp)
        }
        Choice::Create(org) => {
            let mut body = json!({ "org": org, "name": args.name.as_deref().unwrap_or(folder) });
            if let Some(repo) = &detected {
                body["repo_full_name"] = json!(repo);
            }
            let resp = client
                .post("/v1/cli/projects", &body)
                .map_err(|e| match e {
                    ApiError::Status { status: 404, .. } => {
                        Failure::new("org_not_found", 2, format!("no org {org} for this login"))
                    }
                    e => fail(e),
                })?;
            let slug = resp["slug"].as_str().ok_or_else(bad_body)?.to_string();
            (slug, org, true, resp)
        }
    };

    let key = resp["project_key"]
        .as_str()
        .and_then(|k| validate_publishable_key(k).ok())
        .ok_or_else(bad_body)?;
    let status = resp["repo"]["status"].as_str().unwrap_or("unlinked");
    let mut repo = json!({ "status": status, "detected": detected });
    if status != "linked" {
        repo["github_install_url"] = resp["repo"]["github_install_url"].clone();
    }
    Ok(Link {
        dashboard_url: resp["dashboard_url"]
            .as_str()
            .map(String::from)
            .unwrap_or_else(|| format!("{base}/{slug}")),
        slug,
        org,
        created,
        key,
        cloud_url: base,
        repo,
    })
}

enum Choice {
    Existing(String),
    Create(String),
}

fn bad_body() -> Failure {
    ApiError::BadBody.into_failure()
}

fn list_projects(client: &Client, org: Option<&str>) -> Result<Vec<Value>, ApiError> {
    let path = match org {
        Some(o) => format!("/v1/cli/projects?org={o}"),
        None => "/v1/cli/projects".to_string(),
    };
    Ok(client.get(&path)?["projects"]
        .as_array()
        .cloned()
        .unwrap_or_default())
}

fn needs_selection(orgs: &[Value], projects: &[Value], message: &str) -> Failure {
    let pick = |v: &Value, keys: &[&str]| -> Value {
        keys.iter()
            .map(|k| (k.to_string(), v.get(*k).cloned().unwrap_or(Value::Null)))
            .collect::<serde_json::Map<_, _>>()
            .into()
    };
    Failure::new("needs_selection", 2, message)
        .with(
            "orgs",
            orgs.iter().map(|o| pick(o, &["slug", "name"])).collect(),
        )
        .with(
            "projects",
            projects
                .iter()
                .map(|p| pick(p, &["slug", "name", "org", "repo"]))
                .collect(),
        )
}

/// `None` when the person cancels a prompt.
fn prompt(
    client: &Client,
    orgs: &[Value],
    org: Option<String>,
) -> Result<Option<Choice>, ApiError> {
    let slug = |v: &Value| v["slug"].as_str().unwrap_or_default().to_string();
    let Some(org) = org.or_else(|| prompt_org(orgs)) else {
        return Ok(None);
    };
    let projects = list_projects(client, Some(&org))?;
    let mut items: Vec<String> = projects
        .iter()
        .map(|p| format!("{} ({})", slug(p), p["repo"].as_str().unwrap_or("no repo")))
        .collect();
    items.push("Create a new project".to_string());
    Ok(
        match Select::new()
            .with_prompt("Which project?")
            .items(&items)
            .default(0)
            .interact_opt()
        {
            Ok(Some(i)) if i < projects.len() => Some(Choice::Existing(slug(&projects[i]))),
            Ok(Some(_)) => Some(Choice::Create(org)),
            _ => None,
        },
    )
}

/// `None` when there is no org or the person cancels.
fn prompt_org(orgs: &[Value]) -> Option<String> {
    let items: Vec<String> = orgs
        .iter()
        .map(|o| o["slug"].as_str().unwrap_or_default().to_string())
        .collect();
    if items.is_empty() {
        return None;
    }
    match Select::new()
        .with_prompt("Which org?")
        .items(&items)
        .default(0)
        .interact_opt()
    {
        Ok(Some(i)) => Some(items[i].clone()),
        _ => None,
    }
}

fn detect_github_repo(root: &Path) -> Option<String> {
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["remote", "get-url", "origin"])
        .stderr(std::process::Stdio::null())
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    parse_github_remote(&String::from_utf8_lossy(&out.stdout))
}

/// `owner/repo` when the remote points at GitHub.
fn parse_github_remote(url: &str) -> Option<String> {
    let url = url.trim();
    let (authority, path) = match url.split_once("://") {
        Some((_, rest)) => rest.split_once('/')?,
        // scp-like form: `git@github.com:owner/repo.git`.
        None => url.split_once(':')?,
    };
    let host = authority.rsplit('@').next()?.split(':').next()?;
    if !host.eq_ignore_ascii_case("github.com") {
        return None;
    }
    let path = path.trim_end_matches('/');
    let path = path.strip_suffix(".git").unwrap_or(path);
    let (owner, repo) = path.split_once('/')?;
    if owner.is_empty() || repo.is_empty() || repo.contains('/') {
        return None;
    }
    Some(format!("{owner}/{repo}"))
}

fn report_no_workspace(json: bool) {
    if json {
        let payload = serde_json::json!({ "ok": false, "error": "no_workspace" });
        println!("{}", serde_json::to_string_pretty(&payload).unwrap());
        return;
    }
    eprintln!("{} no dif.sh workspace here.", style("✗").red().bold());
    eprintln!(
        "    run {} first (or {} to scaffold + connect in one step).",
        style("dif init").bold(),
        style("dif init --key <dif_pk_…>").bold(),
    );
}

fn success_json(config: &str, switched_from_custom: bool, link: Option<&Link>) -> Value {
    let mut payload = serde_json::json!({
        "ok": true,
        "config": config,
        "mode": "cloud",
        "switched_from_custom": switched_from_custom,
        "next": "dif build",
    });
    if let Some(l) = link {
        payload["project"] = json!({ "slug": l.slug, "org": l.org, "created": l.created });
        payload["dashboard_url"] = json!(l.dashboard_url);
        payload["repo"] = l.repo.clone();
    }
    payload
}

fn report_success(switched_from_custom: bool, link: Option<&Link>, json: bool) {
    let config = Path::new(paths::CONFIG_FILE).display().to_string();
    if json {
        let payload = success_json(&config, switched_from_custom, link);
        println!("{}", serde_json::to_string_pretty(&payload).unwrap());
        return;
    }
    let check = style("✓").green().bold();
    println!("{check} connected {config} to dif.sh Cloud");
    if let Some(l) = link {
        let verb = if l.created { "created" } else { "linked" };
        println!("  {verb} project {} ({})", l.slug, l.dashboard_url);
        if let Some(url) = l.repo["github_install_url"].as_str() {
            println!("  Install the GitHub App to sync specs: {url}");
        }
    }
    if switched_from_custom {
        println!(
            "{} switched events mode custom → cloud; your dif/events/{{exposure,track}}.ts are no longer used",
            style("⚠").yellow().bold(),
        );
    }
    println!(
        "  next: run {} to regenerate the client with your key",
        style("dif build").bold(),
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::cloud::fake_server::FakeServer;

    fn args() -> Args {
        Args {
            key: None,
            url: None,
            org: None,
            project: None,
            create: false,
            name: None,
        }
    }

    fn env_with_token(url: Option<&str>) -> CloudEnv {
        CloudEnv {
            config_dir: None,
            token: Some("dif_cli_t".into()),
            cloud_url: url.map(String::from),
        }
    }

    #[test]
    fn not_logged_in_is_a_precondition_error() {
        let tmp = tempfile::tempdir().unwrap();
        let env = CloudEnv {
            config_dir: Some(tmp.path().join("dif")),
            ..CloudEnv::default()
        };
        let f = link_project(tmp.path(), &args(), &env, false, "shop").unwrap_err();
        assert_eq!(f.exit, 2);
        assert_eq!(f.to_json()["ok"], false);
        assert_eq!(f.to_json()["error"], "not_logged_in");
    }

    #[test]
    fn needs_selection_lists_orgs_and_all_projects() {
        let server = FakeServer::start(|req| {
            match req.path.as_str() {
            "/v1/cli/whoami" => (
                200,
                r#"{"user":{"id":"u1","email":"e"},"orgs":[
                    {"slug":"acme","name":"Acme","role":"owner"},
                    {"slug":"beta","name":"Beta","role":"member"}]}"#
                    .into(),
            ),
            "/v1/cli/projects" => (
                200,
                r#"{"projects":[{"slug":"acme-shop","name":"acme-shop","org":"acme","repo":"acme/shop","role":"owner"},
                    {"slug":"beta-app","name":"Beta App","org":"beta","repo":null,"role":"member"}]}"#
                    .into(),
            ),
            _ => (404, r#"{"error":"not_found"}"#.into()),
        }
        });
        let tmp = tempfile::tempdir().unwrap();
        let env = env_with_token(Some(&server.url));

        let f = link_project(tmp.path(), &args(), &env, false, "shop").unwrap_err();
        assert_eq!((f.code, f.exit), ("needs_selection", 2));
        let v = f.to_json();
        assert_eq!(
            v["orgs"],
            json!([{ "slug": "acme", "name": "Acme" }, { "slug": "beta", "name": "Beta" }])
        );
        assert_eq!(
            v["projects"],
            json!([
                { "slug": "acme-shop", "name": "acme-shop", "org": "acme", "repo": "acme/shop" },
                { "slug": "beta-app", "name": "Beta App", "org": "beta", "repo": null }
            ])
        );
        assert_eq!(server.paths(), ["/v1/cli/whoami", "/v1/cli/projects"]);
    }

    #[test]
    fn single_org_is_selected_for_the_project_list() {
        let server = FakeServer::start(|req| match req.path.as_str() {
            "/v1/cli/whoami" => (200, r#"{"orgs":[{"slug":"acme","name":"Acme"}]}"#.into()),
            _ => (200, r#"{"projects":[]}"#.into()),
        });
        let tmp = tempfile::tempdir().unwrap();
        let env = env_with_token(Some(&server.url));

        let f = link_project(tmp.path(), &args(), &env, false, "shop").unwrap_err();
        assert_eq!(f.code, "needs_selection");
        assert_eq!(server.paths()[1], "/v1/cli/projects?org=acme");
    }

    const KEY: &str = "dif_pk_live_abc123";

    #[test]
    fn links_an_existing_project() {
        let server = FakeServer::start(|req| {
            match req.path.as_str() {
            "/v1/cli/whoami" => (200, r#"{"orgs":[{"slug":"acme","name":"Acme"}]}"#.into()),
            "/v1/cli/projects?org=acme" => (
                200,
                r#"{"projects":[{"slug":"acme-shop","name":"acme-shop","org":"acme","repo":null}]}"#
                    .into(),
            ),
            "/v1/cli/projects/acme-shop/key" => (
                200,
                format!(r#"{{"project_key":"{KEY}","repo":{{"status":"unlinked"}}}}"#),
            ),
            _ => (404, r#"{"error":"not_found"}"#.into()),
        }
        });
        let tmp = tempfile::tempdir().unwrap();
        let env = env_with_token(Some(&server.url));
        let a = Args {
            project: Some("acme-shop".into()),
            ..args()
        };

        let link = link_project(tmp.path(), &a, &env, false, "shop").unwrap();
        assert_eq!(
            (link.slug.as_str(), link.org.as_str()),
            ("acme-shop", "acme")
        );
        assert!(!link.created);
        assert_eq!(link.key, KEY);
        assert_eq!(link.cloud_url, server.url);
        assert_eq!(link.dashboard_url, format!("{}/acme-shop", server.url));
        // The contract sends null when Cloud has no GitHub App.
        assert_eq!(
            link.repo,
            json!({ "status": "unlinked", "detected": null, "github_install_url": null })
        );

        let v = success_json("dif/config.yaml", false, Some(&link));
        assert_eq!(
            v,
            json!({
                "ok": true,
                "project": { "slug": "acme-shop", "org": "acme", "created": false },
                "config": "dif/config.yaml",
                "mode": "cloud",
                "switched_from_custom": false,
                "dashboard_url": format!("{}/acme-shop", server.url),
                "repo": { "status": "unlinked", "detected": null, "github_install_url": null },
                "next": "dif build",
            })
        );
    }

    #[test]
    fn creates_a_project_in_the_only_org() {
        let server = FakeServer::start(|req| match (req.method.as_str(), req.path.as_str()) {
            ("GET", "/v1/cli/whoami") => {
                (200, r#"{"orgs":[{"slug":"acme","name":"Acme"}]}"#.into())
            }
            ("POST", "/v1/cli/projects") => (
                201,
                format!(
                    r#"{{"slug":"shop","project_key":"{KEY}","dashboard_url":"https://cloud.dif.sh/shop",
                    "repo":{{"status":"unlinked","github_install_url":"https://github.com/apps/dif-sh/installations/new"}}}}"#
                ),
            ),
            _ => (404, r#"{"error":"not_found"}"#.into()),
        });
        let tmp = tempfile::tempdir().unwrap();
        let env = env_with_token(Some(&server.url));
        let a = Args {
            create: true,
            ..args()
        };

        let link = link_project(tmp.path(), &a, &env, false, "shop").unwrap();
        let body: Value = serde_json::from_str(&server.requests.lock().unwrap()[1].body).unwrap();
        assert_eq!(body, json!({ "org": "acme", "name": "shop" }));
        assert_eq!((link.slug.as_str(), link.org.as_str()), ("shop", "acme"));
        assert!(link.created);
        assert_eq!(link.key, KEY);
        assert_eq!(link.dashboard_url, "https://cloud.dif.sh/shop");

        let v = success_json("dif/config.yaml", true, Some(&link));
        assert_eq!(
            v["project"],
            json!({ "slug": "shop", "org": "acme", "created": true })
        );
        assert_eq!(v["switched_from_custom"], true);
        assert_eq!(
            v["repo"],
            json!({
                "status": "unlinked",
                "detected": null,
                "github_install_url": "https://github.com/apps/dif-sh/installations/new",
            })
        );
    }

    #[test]
    fn a_linked_repo_has_no_install_url() {
        let server = FakeServer::start(|req| match req.path.as_str() {
            "/v1/cli/whoami" => (200, r#"{"orgs":[{"slug":"acme","name":"Acme"}]}"#.into()),
            "/v1/cli/projects?org=acme" => (
                200,
                r#"{"projects":[{"slug":"acme-shop","org":"acme","repo":"acme/shop"}]}"#.into(),
            ),
            _ => (
                200,
                format!(r#"{{"project_key":"{KEY}","repo":{{"status":"linked"}}}}"#),
            ),
        });
        let tmp = tempfile::tempdir().unwrap();
        let env = env_with_token(Some(&server.url));
        let a = Args {
            project: Some("acme-shop".into()),
            ..args()
        };

        let link = link_project(tmp.path(), &a, &env, false, "shop").unwrap();
        assert_eq!(link.repo, json!({ "status": "linked", "detected": null }));
    }

    #[test]
    fn a_404_maps_to_not_found_codes() {
        let server = FakeServer::start(|req| match req.path.as_str() {
            "/v1/cli/whoami" => (200, r#"{"orgs":[{"slug":"acme","name":"Acme"}]}"#.into()),
            "/v1/cli/projects?org=acme" => (
                200,
                r#"{"projects":[{"slug":"acme-shop","org":"acme","repo":null}]}"#.into(),
            ),
            _ => (404, r#"{"error":"not_found"}"#.into()),
        });
        let tmp = tempfile::tempdir().unwrap();
        let env = env_with_token(Some(&server.url));

        let a = Args {
            project: Some("acme-shop".into()),
            ..args()
        };
        let f = link_project(tmp.path(), &a, &env, false, "shop").unwrap_err();
        assert_eq!((f.code, f.exit), ("project_not_found", 2));

        let a = Args {
            create: true,
            ..args()
        };
        let f = link_project(tmp.path(), &a, &env, false, "shop").unwrap_err();
        assert_eq!((f.code, f.exit), ("org_not_found", 2));
    }

    #[test]
    fn events_url_follows_the_session_host() {
        let local = Some("http://localhost:3000");
        assert_eq!(
            events_url(None, Some(DEFAULT_CLOUD_URL), local).as_deref(),
            Some(DEFAULT_CLOUD_URL)
        );
        assert_eq!(events_url(None, Some(DEFAULT_CLOUD_URL), None), None);
        assert_eq!(events_url(None, local, None).as_deref(), local);
    }

    #[test]
    fn parses_github_remotes() {
        for url in [
            "git@github.com:acme/shop.git",
            "https://github.com/acme/shop",
            "https://github.com/acme/shop.git/",
            "https://token@github.com/acme/shop.git",
            "ssh://git@github.com:22/acme/shop.git",
        ] {
            assert_eq!(
                parse_github_remote(url).as_deref(),
                Some("acme/shop"),
                "{url}"
            );
        }
        for url in [
            "git@gitlab.com:acme/shop.git",
            "https://github.com/acme",
            "/srv/git/shop.git",
            "C:\\repos\\shop",
        ] {
            assert_eq!(parse_github_remote(url), None, "{url}");
        }
    }
}
